<template><section class="wrf-ui wrf-results"><div class="wrf-result-controls"><label>计算域<select v-model="domainId"><option v-for="d in domains" :key="d.id" :value="d.id">{{d.id.toUpperCase()}} · {{d.dx}} m</option></select></label><label>变量<select v-model="variableId"><option v-for="v in variables" :key="v.name" :value="v.name">{{v.label||v.name}} {{unitPresentation(v,nativeUnits).unit}}</option></select></label><label class="wrf-unit-control">单位<select v-model="nativeUnits"><option :value="false">常用单位</option><option :value="true">原始单位</option></select></label><button :disabled="frames.length<2" @click="playing=!playing">{{playing?'暂停':'播放'}}</button><span>{{frame?.time||'暂无时次'}}</span></div><div class="wrf-result-map"><DomainMap v-if="precise" :config="mapConfig" :preview="mapPreview" read-only :image-overlay="overlay"/><div v-else class="wrf-legacy"><p>{{product?.geolocation_repair?.message||'该产品缺少可验证的投影定位，仅提供原图预览。'}}</p><img v-if="asset?.url" :src="asset.url" alt="WRF 原始结果预览" @error="imageError=true"></div></div><div class="wrf-timebar"><button :disabled="!frames.length" @click="index=Math.max(0,index-1)">上一帧</button><input type="range" min="0" :max="Math.max(0,frames.length-1)" v-model.number="index" :disabled="!frames.length"><button :disabled="!frames.length" @click="index=Math.min(frames.length-1,index+1)">下一帧</button><span>{{frames.length?index+1:0}} / {{frames.length}}</span></div><p v-if="asset?.error||imageError" role="alert" class="wrf-error">{{asset?.error||'WRF 图像解码失败'}}</p><p v-if="meta?.quality?.status==='partial'" class="wrf-warning">部分结果，未完成的时次或变量不会作为完整预报显示。</p><details v-if="meta.quality?.warnings?.length||qualityRows.length" class="wrf-quality"><summary>产品质量记录</summary><p v-for="(message,n) in meta.quality?.warnings||[]" :key="n">{{message}}</p><p v-for="row in qualityRows" :key="row.label"><b>{{row.label}}</b> · 缺失 {{row.times.length}} 个时次<br>{{row.times.slice(0,30).join(' · ')}}{{row.times.length>30?'…':''}}</p></details><div v-if="frame" class="wrf-legend"><span>{{formatDisplayValue(frame.display_min,displayUnit)}}</span><i v-if="gradient" :style="{background:gradient}"></i><span>{{formatDisplayValue(frame.display_max,displayUnit)}} {{displayUnit.unit}}</span></div><p v-if="frame" class="wrf-legend-note">色标按已发布产品元数据绘制；范围可能裁剪极值，不代表全场最小值和最大值。<span v-if="['RAINC','RAINNC'].includes(variable?.name)"> 此变量为模式起报以来累计降水。</span><span v-if="['U10','V10'].includes(variable?.name)"> U/V 是风分量，不是风速。</span></p></section></template>
<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import DomainMap from './DomainMap.vue';
import {unitPresentation,formatDisplayValue,paletteGradient} from './presentation.js';
const nativeUnits=ref(false);
const props=defineProps({product:Object,assetResponses:Object,disabled:Boolean});const emit=defineEmits(['asset-request','action']);
const meta=computed(()=>props.product?.meta_json||props.product?.meta||props.product||{}),domains=computed(()=>meta.value.domains||[]),domainId=ref(''),variableId=ref(''),index=ref(0),playing=ref(false),requestId=ref(''),imageError=ref(false);
const domain=computed(()=>domains.value.find(d=>d.id===domainId.value)||domains.value[0]),variables=computed(()=>domain.value?.variables||[]),variable=computed(()=>variables.value.find(v=>v.name===variableId.value)||variables.value[0]),frames=computed(()=>variable.value?.frames||[]),frame=computed(()=>frames.value[index.value]);
const precise=computed(()=>domain.value?.geolocation?.status==='reprojected'&&domain.value.geolocation.target_crs==='EPSG:3857'&&domain.value.extent?.length===4&&domain.value.extent.every(Number.isFinite)&&domain.value.extent[0]<domain.value.extent[2]&&domain.value.extent[1]<domain.value.extent[3]);
const qualityRows=computed(()=>Object.entries({...meta.value.quality?.missing_times,...meta.value.quality?.missing_variables}).filter(([,times])=>Array.isArray(times)&&times.length).map(([label,times])=>({label,times})));
const displayUnit=computed(()=>unitPresentation(variable.value,nativeUnits.value));
const gradient=computed(()=>paletteGradient(variable.value?.palette));
const asset=computed(()=>props.assetResponses?.[requestId.value]),overlay=computed(()=>asset.value?.url&&precise.value?{url:asset.value.url,extent:domain.value.extent,target_crs:domain.value.geolocation.target_crs}:null);
const mapConfig=computed(()=>({domains:[],center:null})),mapPreview=computed(()=>({boundaries:[]}));
function firstVariable(preferred=''){return variables.value.find(v=>v.name===preferred)?.name||variables.value.find(v=>v.name==='T2')?.name||variables.value[0]?.name||'';}
watch(()=>props.product,()=>{domainId.value=domains.value.find(d=>d.id===meta.value.default_domain)?.id||domains.value[0]?.id||'';variableId.value=firstVariable(meta.value.default_variable||meta.value.preferred_variable);index.value=0;playing.value=false;},{immediate:true});
watch(domainId,()=>{if(!variables.value.some(v=>v.name===variableId.value))variableId.value=firstVariable();index.value=0;playing.value=false;});
watch(variableId,()=>{index.value=0;playing.value=false;});
watch(()=>frame.value?.url,path=>{imageError.value=false;requestId.value=crypto.randomUUID();if(path)emit('asset-request',{path,requestId:requestId.value});},{immediate:true});
const timer=setInterval(()=>{if(playing.value&&frames.value.length)index.value=(index.value+1)%frames.value.length;},900);onBeforeUnmount(()=>clearInterval(timer));
</script>
